using HealthApp.Application.Abstractions; using HealthApp.Shared.DTOs; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HealthApp.Api.Controllers;
[ApiController,Route("api/outlets/me"),Authorize(Roles="OutletAdmin")]
public sealed class OutletController(IOutletService service):ControllerBase
{ [HttpGet] public async Task<IActionResult> Me()=>Ok(await service.GetCurrentAsync()); [HttpGet("dashboard")] public async Task<IActionResult> Dashboard()=>Ok(new{outlet=await service.GetCurrentAsync(),billing=await service.GetBillingAsync(),mealPlans=(await service.GetPlansAsync()).Count,recipes=(await service.GetRecipesAsync(null)).Count,customers=(await service.GetCustomersAsync()).Count,subscriptions=(await service.GetSubscriptionsAsync()).Count,orders=(await service.GetOrdersAsync()).Count}); [HttpGet("billing")] public async Task<IActionResult> Billing()=>Ok(await service.GetBillingAsync()); [HttpGet("subscription/plans")] public async Task<IActionResult> SubscriptionPlans()=>Ok(await service.GetSaaSPlansAsync()); [HttpPut("subscription")] public async Task<IActionResult> ChangeSubscription(ChangeOutletSubscriptionRequest r)=>Ok(await service.ChangeSubscriptionAsync(r)); [HttpGet("meal-plans")] public async Task<IActionResult> Plans()=>Ok(await service.GetPlansAsync()); [HttpPost("meal-plans")] public async Task<IActionResult> CreatePlan(CreateMealPlanRequest r)=>Ok(await service.CreatePlanAsync(r)); [HttpGet("recipes")] public async Task<IActionResult> Recipes([FromQuery]string? category)=>Ok(await service.GetRecipesAsync(category)); [HttpGet("menu")] public async Task<IActionResult> Menu()=>Ok(await service.GetMenuAsync()); [HttpPut("menu")] public async Task<IActionResult> SaveMenu(BulkMenuRequest r)=>Ok(await service.SaveMenuAsync(r)); [HttpPost("recipes")] public async Task<IActionResult> CreateRecipe(CreateRecipeRequest r)=>Ok(await service.CreateRecipeAsync(r)); [HttpPut("recipes/{recipeId:guid}")] public async Task<IActionResult> UpdateRecipe(Guid recipeId,UpdateRecipeRequest r){var result=await service.UpdateRecipeAsync(recipeId,r);return result is null?NotFound():Ok(result);} [HttpDelete("recipes/{recipeId:guid}")] public async Task<IActionResult> DeleteRecipe(Guid recipeId)=>await service.DeleteRecipeAsync(recipeId)?NoContent():NotFound(); [HttpGet("customers")] public async Task<IActionResult> Customers()=>Ok(await service.GetCustomersAsync()); [HttpGet("subscriptions")] public async Task<IActionResult> Subscriptions()=>Ok(await service.GetSubscriptionsAsync()); [HttpGet("orders")] public async Task<IActionResult> Orders()=>Ok(await service.GetOrdersAsync()); [HttpGet("deliveries")] public async Task<IActionResult> Deliveries()=>Ok(await service.GetDeliveriesAsync()); }
